package com.nori.tc.db.jpa.common.entity.model;

import com.nori.tc.db.jpa.common.entity.base.AbstractUpdatedEntity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.PrePersist;
import jakarta.persistence.Table;
import jakarta.persistence.UniqueConstraint;

/**
 * tc_model_reportid 테이블 매핑 엔티티.
 *
 * [DB 스키마]
 * - report_key  : bigint generated by default as identity (PK)
 * - model_key   : bigint NOT NULL (FK -> tc_model.model_key)
 * - report_id   : varchar(100) NOT NULL
 * - variable_id : varchar(1000) NULL
 * - enabled     : boolean NOT NULL default false
 * - updated_at  : timestamptz NOT NULL default CURRENT_TIMESTAMP
 * - Constraints : UNIQUE (model_key, report_id)
 */
@Entity
@Table(
        name = "tc_model_reportid",
        uniqueConstraints = {
                @UniqueConstraint(
                        name = "uk_tc_model_reportid_model_key_report_id",
                        columnNames = {"model_key", "report_id"}
                )
        }
)
public class TcModelReportIdEntity extends AbstractUpdatedEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "report_key", nullable = false)
    private Long reportKey;

    @Column(name = "model_key", nullable = false)
    private Long modelKey;

    @Column(name = "report_id", length = 100, nullable = false)
    private String reportId;

    @Column(name = "variable_id", length = 1000)
    private String variableId;

    @Column(name = "enabled", nullable = false)
    private Boolean enabled;

    // =========================================================================
    // Constructors (MapStruct & JPA)
    // =========================================================================

    /**
     * 기본 생성자 (필수)
     * - JPA 프록시 생성용
     * - MapStruct 타겟 객체 생성용 (public 필수)
     */
    public TcModelReportIdEntity() {
    }

    /**
     * 전체 인자 생성자
     */
    public TcModelReportIdEntity(
            Long reportKey,
            Long modelKey,
            String reportId,
            String variableId,
            Boolean enabled
    ) {
        this.reportKey = reportKey;
        this.modelKey = modelKey;
        this.reportId = reportId;
        this.variableId = variableId;
        this.enabled = enabled;
    }

    // =========================================================================
    // Lifecycle
    // =========================================================================

    @PrePersist
    protected void onCreate() {
        if (this.enabled == null) {
            this.enabled = Boolean.FALSE;
        }
    }

    // =========================================================================
    // Static Factory
    // =========================================================================

    /**
     * 신규 엔티티 생성 팩토리
     * - Unique Key(model_key, report_id)를 기반으로 초기화한다.
     */
    public static TcModelReportIdEntity newEntity(long modelKey, String reportId) {
        if (modelKey <= 0) {
            throw new IllegalArgumentException("modelKey must be > 0");
        }
        if (reportId == null || reportId.isBlank()) {
            throw new IllegalArgumentException("reportId must not be null/blank");
        }

        TcModelReportIdEntity e = new TcModelReportIdEntity();
        e.setModelKey(modelKey);
        e.setReportId(reportId);
        return e;
    }

    // =========================================================================
    // Getters & Setters
    // =========================================================================

    public Long getReportKey() {
        return reportKey;
    }

    public void setReportKey(Long reportKey) {
        this.reportKey = reportKey;
    }

    public Long getModelKey() {
        return modelKey;
    }

    public void setModelKey(Long modelKey) {
        this.modelKey = modelKey;
    }

    public String getReportId() {
        return reportId;
    }

    public void setReportId(String reportId) {
        this.reportId = reportId;
    }

    public String getVariableId() {
        return variableId;
    }

    public void setVariableId(String variableId) {
        this.variableId = variableId;
    }

    public Boolean getEnabled() {
        return enabled;
    }

    public void setEnabled(Boolean enabled) {
        this.enabled = enabled;
    }
}
